      sentence = "On this point, you can send your underlings to confirm this yourself.",
      voice = 2,
      next = {13}
    },
    [13] = {
      beijing = 2253,
      dialog = 3,
      music = "PW_8_MysteryMelody",
      renwu = "npc",
      role1 = 2112000,
      role2 = 202101,
      role3 = 202201,
      role6 = 21125003,
      ruchang = 9,
      sentence = "As he shifted gears in the conversation, he produced from his breast pocket a border pass document and handed it to me. Meanwhile, his gaze fell upon a patch of shadow amidst the moonlight.",
      next = {14}
    },
    [14] = {
      beijing = 2253,
      dialog = 3,
      music = "PW_8_MysteryMelody",
      renwu = "npc",
      sentence = "I gave a start. Had he known all along that I had a secret guard following us?",
      next = {15}
    },
    [15] = {
      beijing = 2253,
      dialog = 3,
      music = "PW_8_MysteryMelody",
      renwu = "npc",
      sentence = "I warily scanned the border document before me, then raised my hand slightly.",
      next = {16}
    },
    [16] = {
      beijing = 2253,
      dhead = 1302,
      dialog = 1,
      music = "PW_8_MysteryMelody",
      renming = "$u",
      renwu = "npc",
      sentence = "Go look into this.",
      next = {17}
    },
    [17] = {
      beijing = 2253,
      dialog = 3,
      music = "PW_8_MysteryMelody",
      renwu = "npc",
      sentence = "In a twinkling, a figure landed between us, taking the document from Lucien's hand and then disappearing again into the darkness.",
      next = {18}
    },
    [18] = {
      beijing = 2253,
      dialog = 3,
      music = "PW_8_MysteryMelody",
      renwu = "npc",
      sentence = "A silence fell over the air again. The guards searching for us apparently had picked up our trail, because the torches converged and hurried in our direction.",
      next = {19}
    },
    [19] = {
      beijing = 2253,
      dialog = 3,
      music = "PW_8_MysteryMelody",
      renwu = "npc",
      sentence = "But the man wasn't at all panicked. He put an arm around me and tip-toed along the night breeze, drifting over the roof tiles and eaves.",
      next = {20}
    },
    [20] = {
      beijing = 2253,
      dialog = 3,
      music = "PW_8_MysteryMelody",
      renwu = "npc",
      sentence = "The full moon had never seemed so close. The frigid wind swept past my ears as my eyes gazed up at his face. His body under my fingertips felt taut and powerful.",
      next = {21}
    },
    [21] = {
      beijing = 2253,
      dialog = 3,
      music = "PW_8_MysteryMelody",
      renwu = "npc",
      sentence = "That blurry image from the rumors gradually receded into obscurity. I didn't know why, but I thought that this was more like what \"Lucien\" should be after all.",
      next = {22}
    },
    [22] = {
      beijing = 2253,
      dhead = 1308,
      dialog = 1,
      music = "PW_8_MysteryMelody",
      renming = "$u",
      renwu = "npc",
      sentence = "Three years ago you fell gravely ill, and then were beset with myriad health problems. You never set so much as half a foot outside your mansion, you didn't attend to matters of government. You were reduced to the status of a commoner.",
      next = {23}
    },
    [23] = {
      beijing = 2253,
      dhead = 1308,
      dialog = 1,
      music = "PW_8_MysteryMelody",
      renming = "$u",
      renwu = "npc",
      sentence = "If you truly are Lucien, don't you think the disparity between who you are and what the rumors say is a little much?",
      next = {24}
    },
    [24] = {
      beijing = 2253,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "PW_8_MysteryMelody",
      renming = "Lucien",
      renwu = "npc",
      role1 = 2111000,
      role2 = 201106,
      role3 = 201201,
      role5 = 2111404,
      role6 = 21125003,
      ruchang = -1,
      sentence = "If we're really going to be wed, naturally I'm glad to be frank with you, Princess.",
      voice = 2,
      next = {25}
    },
    [25] = {
      beijing = 2253,
      dialog = 3,
      music = "PW_8_MysteryMelody",
      renwu = "npc",
      role1 = 2111000,
      role2 = 201106,
      role3 = 201204,
      role5 = 2111404,
      role6 = 21125003,
      sentence = "Although that's what he said, in his eyes there wasn't a hint of emotion.",
      next = {26}
    },
    [26] = {
      beijing = 2253,
      dialog = 3,
      music = "PW_8_MysteryMelody",
      renwu = "npc",
      role1 = 2111000,
      role2 = 201106,
      role3 = 201204,
      role5 = 2111404,
      role6 = 21125003,
      sentence = "As if he was growing fatigued from hiding something, the cool aloofness under his gentle facade started to show through.",
      next = {27}
    },
    [27] = {
      beijing = 2253,
      dialog = 3,
      music = "PW_8_MysteryMelody",
      renwu = "npc",
      role1 = 2111000,
      role2 = 201106,
      role3 = 201204,
      role5 = 2111404,
      role6 = 21125003,
      sentence = "Seeing him like this, I had no intention of using pretend politeness with him again.",
      next = {28}
    },
    [28] = {
      beijing = 2253,
      dhead = 1302,
      dialog = 1,
      music = "PW_8_MysteryMelody",
      renming = "$u",
      renwu = "npc",
      role1 = 2111000,
      role2 = 201105,
      role3 = 201204,
      role5 = 2111404,
      role6 = 21125003,
      sentence = "You said you gave them a month, which means you were well-prepared for this assassination. So why did you abandon it?",
      next = {29}
    },
    [29] = {
      beijing = 2253,
      dhead = 1302,
      dialog = 1,
      music = "PW_8_MysteryMelody",
      renming = "$u",
      renwu = "npc",
      role1 = 2111000,
      role2 = 201105,
      role3 = 201204,
      role5 = 2111404,
      role6 = 21125003,
      sentence = "Do you know who's pulling the strings behind the scenes? What is their goal?",
      next = {30}
    },
    [30] = {
      beijing = 2253,
      dhead = 1302,
      dialog = 1,
      music = "PW_8_MysteryMelody",
      renming = "$u",
      renwu = "npc",
      role1 = 2111000,
      role2 = 201105,
      role3 = 201204,
      role5 = 2111404,
      role6 = 21125003,
      sentence = "And what's your goal?",
