      dialog = 3,
      music = "PW_8_MysteryMelody",
      renwu = "npc",
      role1 = 2111000,
      role2 = 201105,
      role3 = 201201,
      role5 = 2111404,
      role6 = 21125003,
      sentence = "As I calmly grilled him, Lucien's eyes curved up more, and a knowing smile formed on his lips.",
      next = {32}
    },
    [32] = {
