      music = "PW_8_MysteryMelody",
      renming = "Lucien",
      renwu = "npc",
      role1 = 2111000,
      role2 = 201107,
      role3 = 201201,
      role5 = 2111404,
      role6 = 21125003,
      sentence = "I've heard that the Princess of West City was exceedingly intelligent, and she selected the good and the capable after the old emperor passed and has maintained stability in Westia...",
      voice = 2,
      next = {33}
    },
    [33] = {
      beijing = 2253,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "PW_8_MysteryMelody",
      renming = "Lucien",
      renwu = "npc",
      role1 = 2111000,
      role2 = 201107,
      role3 = 201201,
      role5 = 2111404,
      role6 = 21125003,
      sentence = "...but sure enough, seeing her in real person is even more impressive.",
      voice = 2,
      next = {34}
    },
    [34] = {
      beijing = 2253,
      dhead = 1302,
      dialog = 1,
      music = "PW_8_MysteryMelody",
