      renwu = "npc",
      role1 = 2111000,
      role2 = 201106,
      role3 = 201201,
      role5 = 2111404,
      role6 = 21125003,
      sentence = "As I looked straight at him, I saw Lucien land casually on another rooftop eave, then stare coolly at the imperial city standing in the distance.",
