      role2 = 201106,
      role3 = 201204,
      role5 = 2111404,
      role6 = 21125003,
      sentence = "The person behind the scenes is the current Emperor of Jubilee. Your uncle is probably also involved.",
      voice = 2,
      next = {37}
    },
    [37] = {
      beijing = 2253,
      dialog = 3,
