      renwu = "npc",
      role1 = 2111000,
      role2 = 201106,
      role3 = 201204,
      role5 = 2111404,
      role6 = 21125003,
      sentence = "After the ceremony, you will become the rightful empress of Westia.",
      voice = 2,
