    },
    [41] = {
      beijing = 2253,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "PW_8_MysteryMelody",
      renming = "Lucien",
      renwu = "npc",
      role1 = 2111000,
      role2 = 201105,
      role3 = 201201,
      role5 = 2111404,
      role6 = 21125003,
      sentence = "An easily manipulated puppet by your side day and night would certainly be better than your uncle if one wanted to make a move against you.",
      voice = 2,
      next = {42}
    },
    [42] = {
      beijing = 2253,
      dialog = 3,
      music = "PW_8_MysteryMelody",
      renwu = "npc",
      role1 = 2111000,
      role2 = 201105,
      role3 = 201201,
      role5 = 2111404,
      role6 = 21125003,
      roleanim = 1.1,
      sentence = "A subtle laugh suffused the air. Lucien leaned in close to my ear, his warm and tender breath brushing past with a hint of chill.",
      next = {43}
    },
    [43] = {
