      role3 = 201201,
      role5 = 2111404,
      role6 = 21125003,
      roleanim = 1.1,
      sentence = "And even if they can't move against you, the person by your pillow will have more opportunities to influence and control you.",
      voice = 2,
      next = {44}
    },
    [44] = {
      beijing = 2253,
      dialog = 2,
      idx = 2,
