      role1 = 2111000,
      role2 = 201105,
      role3 = 201201,
      role5 = 2111404,
      role6 = 21125003,
      roleanim = 1.1,
      sentence = "Whether for your uncle or Jubilee, it will do more good than harm, and what they do will be well within their rights.",
      voice = 2,
      next = {45}
    },
    [45] = {
      beijing = 2253,
      dialog = 3,
      music = "PW_8_MysteryMelody",
      renwu = "npc",
      role1 = 2111000,
      role2 = 201105,
      role3 = 201201,
      role5 = 2111404,
      role6 = 21125003,
      roleanim = 1.1,
      sentence = "I stood stock still, only tilting my head a bit to the side. Our breaths intermingled, and it seemed like just another half-inch and I'd be touching that enchanting moonlight.",
      next = {46}
    },
    [46] = {
      beijing = 2253,
      dhead = 1308,
      dialog = 1,
      music = "PW_8_MysteryMelody",
      renming = "$u",
      renwu = "npc",
      role1 = 2111000,
      role2 = 201105,
      role3 = 201201,
      role5 = 2111404,
      role6 = 21125003,
      roleanim = 1.1,
      sentence = "I have no reason to believe you. After all, your appearance is all too convenient, as if all this has been put in front of me on purpose...",
      next = {47}
    },
    [47] = {
      beijing = 2253,
      dialog = 3,
      music = "PW_8_MysteryMelody",
      renwu = "npc",
      role1 = 2111000,
      role2 = 201105,
      role3 = 201201,
      role5 = 2111404,
      role6 = 21125003,
      roleanim = 1.1,
      sentence = "I suddenly came to a pause.",
      next = {48}
    },
    [48] = {
      beijing = 2253,
      dialog = 3,
      music = "PW_8_MysteryMelody",
      renwu = "npc",
      role1 = 2111000,
      role2 = 201107,
      role3 = 201201,
      role5 = 2111404,
      role6 = 21125003,
      roleanim = 1.1,
      sentence = "The entire night sky was blocked out behind him. Under those eyes filling with ambition, I couldn't help but want to take a step back.",
      next = {49}
    },
    [49] = {
      beijing = 2253,
      dialog = 3,
      music = "PW_8_MysteryMelody",
      renwu = "npc",
      role1 = 2111000,
      role2 = 201107,
      role3 = 201201,
      role5 = 2111404,
      role6 = 21125003,
      roleanim = 1.1,
      sentence = "But an arm wrapped itself around me, pulling tight across my lower back, drawing our muffled breaths even closer together.",
      next = {50}
    },
    [50] = {
      beijing = 2253,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "PW_8_MysteryMelody",
      renming = "Lucien",
      renwu = "npc",
      role1 = 2111000,
      role2 = 201107,
      role3 = 201201,
      role5 = 2111404,
      role6 = 21125003,
      roleanim = 1.1,
      sentence = "You raised four questions, Princess. I haven't finished answering yet.",
      voice = 2,
      next = {51}
    },
    [51] = {
      beijing = 2253,
      dialog = 3,
      music = "PW_8_MysteryMelody",
      renwu = "npc",
      role1 = 2111000,
      role2 = 201107,
      role3 = 201201,
      role5 = 2111404,
      role6 = 21125003,
      roleanim = 1.1,
      sentence = "Unlike the icy exterior of his face, the warmth of his body under my palm and his pressing aura left me a bit anxious.",
      next = {52}
    },
    [52] = {
