      dialog = 2,
      idx = 2,
      male = 2,
      music = "PW_8_MysteryMelody",
      renming = "Lucien",
      renwu = "npc",
      role1 = 2111000,
      role2 = 201107,
      role3 = 201201,
      role5 = 2111404,
      role6 = 21125003,
      roleanim = 1.1,
      sentence = "This indeed should have been an ordinary marriage alliance, but even a worm will turn. All I'm doing is just adding a little more fuel to the fire.",
      voice = 2,
      next = {53}
    },
    [53] = {
      beijing = 2253,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "PW_8_MysteryMelody",
      renming = "Lucien",
      renwu = "npc",
      role1 = 2111000,
      role2 = 201107,
      role3 = 201201,
      role5 = 2111404,
      role6 = 21125003,
      roleanim = 1.1,
      sentence = "If I resisted them and made it to Westia's imperial city, then some things would remain hidden for a lifetime, and I would go on living in fear.",
      voice = 2,
      next = {54}
    },
    [54] = {
      beijing = 2253,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "PW_8_MysteryMelody",
