      renwu = "npc",
      role1 = 2111000,
      role2 = 201107,
      role3 = 201201,
      role5 = 2111404,
      role6 = 21125003,
      roleanim = 1.1,
      sentence = "So I might as well give them an opportunity.",
      voice = 2,
      next = {55}
    },
    [55] = {
