      role1 = 2111000,
      role2 = 201107,
      role3 = 201201,
      role5 = 2111404,
      role6 = 21125003,
      roleanim = 1.1,
      sentence = "After all, sometimes the muck and rot needs to be washed away before one can make a clean cut.",
