      role1 = 2111000,
      role2 = 201107,
      role3 = 201201,
      role5 = 2111404,
      role6 = 21125003,
      roleanim = 1.1,
      sentence = "He gently lifted his hand, pushing a few stray strands of my hair back behind my ear with his icy fingers, intentionally brushing against the burning tip of my ear.",
      next = {57}
    },
    [57] = {
      beijing = 2253,
      dialog = 2,
      idx = 2,
