      renwu = "npc",
      role1 = 2111000,
      role2 = 201107,
      role3 = 201201,
      role5 = 2111404,
      role6 = 21125003,
      roleanim = 1.1,
      sentence = "\"Grand Prince Lucien\" is merely a title to you, Princess. He could be anyone.",
      voice = 2,
      next = {58}
    },
    [58] = {
      beijing = 2253,
      dialog = 2,
      idx = 2,
