      role1 = 2111000,
      role2 = 201107,
      role3 = 201201,
      role5 = 2111404,
      role6 = 21125003,
      roleanim = 1.1,
      ruchang = 9,
      sentence = "So, have you enjoyed the moon tonight, Princess?",
      voice = 2,
      next = {59}
    },
    [59] = {
      beijing = 3751,
      bganim = 0,
      dialog = 3,
      music = "PW_1_QuiteNight",
      renwu = "npc",
      sentence = "The next day, news that the princess had been kidnapped spread throughout the whole city. The regent king gave the order to seal off the entire city, and to stop at nothing to apprehend the criminal and rescue the princess.",
      next = {60}
    },
    [60] = {
      beijing = 3751,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "PW_1_QuiteNight",
      renming = "Lucien",
      renwu = "npc",
      role1 = 2112000,
      role2 = 202101,
      role3 = 202201,
      role6 = 21125003,
      ruchang = -1,
      sentence = "The princess was kidnapped last night. If the kidnapper really wanted to get away, they would've already done so yesterday night. And yet it was not until 9 o'clock this morning did the city seal off its gate.",
      voice = 2,
      next = {61}
    },
    [61] = {
      beijing = 3751,
      dialog = 3,
      music = "PW_1_QuiteNight",
      renwu = "npc",
      role1 = 2112000,
      role2 = 202101,
      role3 = 202201,
      role6 = 21125003,
      sentence = "Lucien sat beside the tea table with a hand on his chin.",
      next = {62}
    },
    [62] = {
      beijing = 3751,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "PW_1_QuiteNight",
      renming = "Lucien",
      renwu = "npc",
      role1 = 2112000,
      role2 = 202101,
      role3 = 202201,
      role6 = 21125003,
      sentence = "It appears your uncle isn't too interested in actually rescuing you.",
      voice = 2,
      next = {63}
    },
    [63] = {
      beijing = 3751,
      dhead = 1302,
      dialog = 1,
