      renming = "$u",
      renwu = "npc",
      role1 = 2112000,
      role2 = 202101,
      role3 = 202201,
      role6 = 21125003,
      sentence = "My remaining here is no indication that I trust you, just that this is indeed an opportunity.",
      next = {64}
    },
    [64] = {
      beijing = 3751,
      dhead = 1309,
      dialog = 1,
      music = "PW_1_QuiteNight",
      renming = "$u",
      renwu = "npc",
      role1 = 2112000,
      role2 = 202101,
      role3 = 202201,
      role6 = 21125003,
      sentence = "Besides, you could be more straight-forward with your words: he's mad that I wasn't killed on the spot.",
      next = {65}
    },
    [65] = {
      beijing = 3751,
      dialog = 3,
      music = "PW_1_QuiteNight",
      renwu = "npc",
      role1 = 2112000,
      role2 = 202101,
      role3 = 202201,
      role6 = 21125003,
      sentence = "Not taking Lucien's sarcasm to heart, I looked at the vellum map in my hand.",
      next = {66}
    },
