      beijing = 3751,
      dhead = 1308,
      dialog = 1,
      music = "PW_1_QuiteNight",
      renming = "$u",
      renwu = "npc",
      role1 = 2112000,
      role2 = 202101,
      role3 = 202201,
      role6 = 21125003,
      sentence = "If one really cracked the whip, it would take at least a month to make it to Jubilee and back... and then still need to investigate my uncle and the escort convoy...",
      next = {67}
    },
    [67] = {
      beijing = 3751,
      dhead = 1308,
      dialog = 1,
      music = "PW_1_QuiteNight",
      renming = "$u",
      renwu = "npc",
      role1 = 2112000,
      role2 = 202101,
      role3 = 202201,
      role6 = 21125003,
      sentence = "Delaying the marriage ceremony seven days... but one also can't give the people the impression someone was trying to impede this symbolic gesture of peace.",
      next = {68}
    },
    [68] = {
      beijing = 3751,
      dialog = 3,
      music = "PW_1_QuiteNight",
      renwu = "npc",
      role1 = 2112000,
      role2 = 202101,
      role3 = 202201,
